// HasProduct applies the HasEdge predicate on the "product" edge.
func HasProduct() predicate.Finding {
	return predicate.Finding(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldId),
			sqlgraph.Edge(sqlgraph.M2O, false, ProductTable, ProductColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasProductWith applies the HasEdge predicate on the "product" edge with a given conditions (other predicates).
func HasProductWith(preds ...predicate.Tenant) predicate.Finding {
	return predicate.Finding(func(s *sql.Selector) {
		step := newProductStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasAcceptedBy applies the HasEdge predicate on the "accepted_by" edge.
func HasAcceptedBy() predicate.Finding {
	return predicate.Finding(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldId),
			sqlgraph.Edge(sqlgraph.M2O, false, AcceptedByTable, AcceptedByColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasAcceptedByWith applies the HasEdge predicate on the "accepted_by" edge with a given conditions (other predicates).
func HasAcceptedByWith(preds ...predicate.Operator) predicate.Finding {
	return predicate.Finding(func(s *sql.Selector) {
		step := newAcceptedByStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.Finding) predicate.Finding {
	return predicate.Finding(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.Finding) predicate.Finding {
	return predicate.Finding(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.Finding) predicate.Finding {
	return predicate.Finding(sql.NotPredicates(p))
}
